type OrderResult = { ok: true } | { ok: false; error: string };
type Cart = { items: Array<{ sku: string; quantity: number }> };
type UI = { submitting: boolean; success: boolean };
export function finishCheckout(result: OrderResult, cart: Cart, ui: UI) {
  if (!result.ok) {
    cart.items = [];
    ui.submitting = false;
    return;
  }
  ui.submitting = false;
  ui.success = true;
}
